    try Self.checkAlphaSurvivesTheSize(settings, canvas: canvas)
    let output = Self.videoReadOutput(built, settings: settings)
    guard videoReader!.canAdd(output) else {
        throw Exporter.ExportError.failed(
            "The composition could not be read for export.")
    }
    videoReader!.add(output)

    // An encoder row's packets go in as they are (`ExportEncodePump`).
    let pump = settings.writer == ExportEncodePump.av1Writer
        ? try ExportEncodePump(settings: settings, canvas: canvas, range: range) : nil
    let input = try pump.map {
        AVAssetWriterInput(
            mediaType: .video, outputSettings: nil, sourceFormatHint: $0.formatDescription)
    destination = url
    range = Exporter.timeRange(settings, composition: built.composition)
    totalSeconds = max(0, CMTimeGetSeconds(range.duration))
    audioEnd = ExportAudioEnd(range: range)
    videoReader = try Self.reader(built.composition, range: range)
    // `ExportWriter.addVideo`'s guard: the placeholder track makes this never empty.
    guard !built.composition.tracks(withMediaType: .video).isEmpty else {
        throw Exporter.ExportError.emptyTimeline
    }
    let canvas = built.videoComposition.renderSize
    try ExportWriter.checkAlphaSurvivesTheSize(settings, canvas: canvas)
    videoOutput = ExportWriter.videoReadOutput(built, settings: settings)
    guard videoReader.canAdd(videoOutput) else {
        throw Exporter.ExportError.failed("The composition could not be read for export.")
    }
    videoReader.add(videoOutput)
    pump = try ExportEncodePump(settings: settings, canvas: canvas, range: range)
    // The silent movie (CX-15 (2)): no sound, no reader, encoder or audio track.
    let hasAudio = !built.composition.tracks(withMediaType: .audio).isEmpty
    audioReader = hasAudio ? try Self.reader(built.composition, range: range) : nil
    audioMaster = hasAudio
        // Milliseconds rather than frames, and no rate in the line: audio
        // has no frames, which is the same reason the rate popup is
        // greyed out for this preset.
        let duration = ReelTime.format(settings.duration, fps: settings.fps, frames: false)
        return "Audio only · \(duration)"
    }
    let duration = ReelTime.format(settings.duration, fps: settings.fps, frames: true)
    var text = "\(settings.width) × \(settings.height) · \(settings.fps.displayName) fps · "
        + duration
    if Self.isFrameSequence(container: settings.container) {
        // What a GIF or an APNG costs is frames, not seconds — and it
        // carries no audio however much of it the timeline has, which is
        // worth saying before the export rather than after it.
        text += " · \(settings.sequenceFrameCount ?? 0) frames, no audio"
    }
    // A bundled encoder's estimate (spec §11 CX-18 (9)).
    if let line = ExportEncoderCosts.sheetLine(for: settings) { text += "\n" + line }
    return text
}

