        encoderSpeed = speed.flatMap(EncoderSpeed.init(rawValue:))
        audioBits = c.lenient(.audioBits)
        stems = c.lenient(.stems, [])
    }

    var renderSize: CGSize { CGSize(width: width, height: height) }
}

